import React from "react";
import { debounce } from "lodash";

const TweetCard = ({ tweet, onDelete, draggableProps, dragHandleProps, innerRef }) => {
  const handleClick = debounce(() => {
    window.open(tweet.profileLink, "_blank");
  }, 300);

  const handleDeleteClick = (e) => {
    e.stopPropagation(); // Prevent interference with dragging
    if (onDelete && typeof onDelete === "function") {
      onDelete(tweet.id);
    }
  };

  return (
    <div
      ref={innerRef}
      {...draggableProps}
      {...dragHandleProps}
      className="relative p-4 bg-white rounded-lg shadow-md hover:shadow-lg transition-all border border-gray-200 w-full cursor-grab active:cursor-grabbing"
    >
      {/* Delete Button (Top-Right) */}
      {onDelete && (
        <button
          onClick={handleDeleteClick}
          className="absolute top-2 right-2 bg-red-500 text-white px-2 py-1 rounded text-sm hover:bg-red-600 transition-colors"
        >
          Delete
        </button>
      )}

      {/* Centered Content */}
      <div className="flex flex-col items-center">
        <img
          src={tweet.profile_pic || "/placeholder.jpg"}
          alt={tweet.author_name}
          className="w-16 h-16 rounded-full mb-2 object-cover"
        />
        <p className="font-semibold text-gray-800">{tweet.author_name}</p>
        <a
          href={tweet.profileLink}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-500 text-sm hover:underline"
          onClick={(e) => {
            e.stopPropagation(); // Prevent blocking drag
            handleClick();
          }}
        >
          @{tweet.author_name}
        </a>
        <p className="text-gray-700 text-center mt-2 break-words">{tweet.content}</p>
        <div className="flex space-x-4 text-gray-500 text-sm mt-2">
          <span className="flex items-center">
            <span className="mr-1">❤️</span> {tweet.likes || 0}
          </span>
          <span className="flex items-center">
            <span className="mr-1">💬</span> {tweet.comments || 0}
          </span>
        </div>
      </div>
    </div>
  );
};

export default TweetCard;


